def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 2D array to store the maximum sum of values collected on the two paths
    # from the top-left corner to the bottom-right corner
    dp = [[0] * N for _ in range(N)]

    # Initialize a 2D array to store the parent coordinates of the maximum sum value for each cell
    parent = [[(-1, -1)] * N for _ in range(N)]

    # Iterate over the grid values and update the maximum sum and parent coordinates
    for row in range(N):
        for col in range(N):
            val = grid_values[row][col]
            if val == 0:
                continue
            dp[row][col] = val
            parent[row][col] = (row, col)
            if row > 0 and col > 0:
                dp[row][col] += max(dp[row - 1][col], dp[row][col - 1])
                parent[row][col] = (row - 1, col) if dp[row - 1][col] > dp[row][col - 1] else (row, col - 1)
            elif row > 0:
                dp[row][col] += dp[row - 1][col]
                parent[row][col] = (row - 1, col)
            elif col > 0:
                dp[row][col] += dp[row][col - 1]
                parent[row][col] = (row, col - 1)

    # Find the maximum sum on the two paths by traversing the parent coordinates
    # from the bottom-right corner to the top-left corner
    sum1 = 0
    sum2 = 0
    curr_row, curr_col = N - 1, N - 1
    while curr_row >= 0 and curr_col >= 0:
        if parent[curr_row][curr_col][0] == curr_row - 1:
            sum1 += grid_values[curr_row][curr_col]
            curr_row -= 1
        else:
            sum2 += grid_values[curr_row][curr_col]
            curr_col -= 1

    return max(sum1, sum2)

