        dp[i][i] = compute_energy(i, i)

    for i in range(len(beads) - 2, -1, -1):
        for j in range(i + 1, len(beads)):
            dp[i][j] = max(dp[i + 1][k] + compute_energy(i, k) for k in range(i + 1, j + 1))

    return dp[0][-1]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = beads[i]
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i+l-1
            dp[i][j] = max(dp[i][k] * dp[k+1][j] for k in range(i, j))
    return dp[0][n-1]

