def count_partitions(n: int, k: int, x: int) -> int:
    # Edge case: If k is 1, there is only one way to partition n
    if k == 1:
        return 1

    # Edge case: If n is smaller than x, there are no partitioning ways
    if n < x:
        return 0

    # Base case: If n is equal to x, there is only one way to partition it
    if n == x:
        return 1

    # Recursive case: Partition n into k parts, each at least x, and count the number of ways
    count = 0
    for i in range(x, n + 1):
        count += count_partitions(n - i, k - 1, x)

    return count

