    class BreadthFirstSearch:
        def __init__(self, A, B, rules):
            self.A = A
            self.B = B
            self.rules = rules
            self.queue = [(A, "")].
            self.steps = 0

        def next_step(self):
            step = self.queue.pop(0)
            for rule in self.rules:
                if rule[0] in step[0]:
                    step[0] = step[0].replace(rule[0], rule[1])
                    self.queue.append((step[0], step[1] + 1))
            return step

        def is_solution(self):
            return self.steps < 10 and self.queue[0][0] == self.B

    bfs = BreadthFirstSearch(A, B, rules)
    while bfs.is_solution():
        bfs.next_step()
    return bfs.steps if bfs.is_solution() else "NO ANSWER!"

