    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        # System 11
        if system == 11 and current_game and opponent_score == 11 - player_score:
            games.append(f"{player_score}:{opponent_score}")
            player_score, opponent_score, current_game = 0, 0, []

        # System 21
        elif system == 21 and player_score == 21 and opponent_score >= 19:
