def calculate_score(system: int, points: str) -> list:
    if system != 11 and system != 21:
        raise ValueError("Invalid scoring system")
    if points.count("W") != points.count("L"):
        raise ValueError("Uneven number of points won")
    if points.count("W") == 0 or points.count("L") == 0:
        raise ValueError("No points won")
    if points[0] == "L":
        raise ValueError("Game started with the opponent's turn")

    player_score = 0
    opponent_score = 0
    game_scores = []
    is_last_game = False
    for i in range(len(points)):
        if points[i] == "W":
            player_score += 1
        else:
            opponent_score += 1
        if player_score == system:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
        if opponent_score == system:
            game_scores.append(f"{player_score}:{opponent_score}")
            break
        if player_score == system - 2:
            is_last_game = True

    if not is_last_game and (player_score != 0 or opponent_score != 0):
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return 1

    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1

    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]

    return dp[n]

def catalan_number(n: int) -> int:
    if n <= 0:
        return 1
    else:
        result = 0
        for i in range(n):
            result += catalan_number(i) * catalan_number(n-i-1)
        return result

def catalan_number(n: int) -> int:
    def catalan_number_helper(n: int) -> int:
        if n == 0:
            return 1
        result = 0
        for i in range(n):
            result += catalan_number_helper(i) * catalan_number_helper(n - i - 1)
        return result
    return catalan_number_helper(n)

