    for herb in sorted(herbs, key=lambda x: x[1], reverse=True):
        if herb[0] <= T:
            max_val += herb[1]
            T -= herb[0]
        else:
            max_val += (T / herb[0]) * herb[1]
            break
    return max_val

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a dictionary to store the maximum volume that can be occupied
    # by any subset of the given items for each i values from 0 to n
    dp = {0: 0}

    # Loop through each item
    for i in range(n):
        # Loop through the previous maximum volume that can be occupied
        for j in range(V):
            # If the current item's volume is less than or equal to the remaining space
            if volumes[i] <= j:
                # Update the maximum volume that can be occupied
                dp[i+1] = max(dp[i], dp[i-1] + volumes[i])
            else:
                # If the current item's volume is greater than the remaining space
                # Update the maximum volume that can be occupied
                dp[i+1] = dp[i]

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n]

def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the maximum volume that can be occupied
    # by any subset of the given items for the first n items.
    table = [[0 for _ in range(n+1)] for _ in range(V+1)]

    # Fill the table with the volumes of the items.
    for i in range(n):
        table[0][i] = volumes[i]

    # Fill the table with the maximum volume that can be occupied
    # by any subset of the given items for the first n items.
    for j in range(1, V+1):
        for i in range(n):
            if j >= volumes[i]:
                table[j][i] = max(table[j-volumes[i]][i-1], volumes[i])
            else:
                table[j][i] = table[j][i-1]

    # Return the minimum remaining space in the box.
    return V - table[V][n-1]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store the maximum volume for each subset of items
    dp = [0] * (n + 1)
    # Loop through the items and calculate the maximum volume for each subset
    for i in range(1, n + 1):
        for j in range(V):
            if j >= volumes[i - 1]:
                dp[i] = max(dp[i], dp[i - 1] + j)
    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:

    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        dp[i] = max(dp[i - 1], volumes[i - 1] + dp[i - 1])
        if dp[i] > V:
            return 0
    return dp[n]

def calculate_arrangements(n, m, a):
    def _helper(n, m, a, cur_type, cur_pots):
        if cur_type == len(a):
            return 1
        if cur_pots == 0:
            return 0
        if cur_type == n:
            return 0
        total = 0
        for i in range(1, min(a[cur_type], cur_pots) + 1):
            total += _helper(n, m - i, a, cur_type + 1, cur_pots - i)
        return total
    return _helper(n, m, a, 0, m) % (10**6 + 7)

def calculate_arrangements(n, m, a):
    """ Computes the number of ways to arrange m pots of flowers using up to n types, where the ith type can have at most a[i] pots, and the arrangement must be in increasing order of flower types. """
    from itertools import combinations, permutations

    # Compute the number of ways to arrange the pots in increasing order of flower types
    # while limiting the number of pots of each type to a[i]
    num_arrangements = 0
    for pot_combo in combinations(range(m), n):
        types = [0] * n
        for pot in pot_combo:
            for i, type in enumerate(types):
                if type <= a[i]:
                    types[i] += 1
                    break
        else:
            continue
        num_arrangements += 1

    return num_arrangements % (10**6 + 7)

def calculate_arrangements(n, m, a):
    # Initialize a list to store the number of arrangements for each type of flower
    num_arrangements = [0] * (n + 1)
    num_arrangements[0] = 1

    # Loop through each type of flower
    for i in range(1, n + 1):
        # Loop through each pot of the current type of flower
        for j in range(min(m, a[i - 1]) + 1):
            # If the current type of flower is the last type, then we can only
            # arrange 1 way (since the order is in increasing order)
            if i == n:
                num_arrangements[i] = 1
            # Otherwise, we can arrange the current type of flower in any order
            # up to its maximum number of pots, and then concatenate the
            # arrangements of the previous types
            else:
                num_arrangements[i] += j * num_arrangements[i - 1]

    # Return the total number of arrangements modulo (10^6 + 7)
    return num_arrangements[n] % (10**6 + 7)

def vigenere_decrypt(key, ciphertext):
    keychars = set(key.lower())
    cipherchars = [c.lower() for c in ciphertext]
    decrypted = []
    for i in range(len(cipherchars)):
        c = cipherchars[i]
        if c not in keychars:
            decrypted.append(c)
            continue
        k = key[i % len(key)]
        if k == c:
            decrypted.append(c)
        else:
            decrypted.append(chr(((ord(c) - ord(k)) % 26) + ord('a')))
    return ''.join(decrypted)

