def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def extended_gcd(a, b):
    if b == 0:
        return (1, 0, a)
    else:
        x, y, g = extended_gcd(b, a % b)
        return (y, x - y * (a // b), g)

def mod_inverse(a, b):
    # Use the Extended Euclidean Algorithm to find the modular inverse of a modulo b
    g, x, y = egcd(a, b)
    if g != 1:
        return None
    return x % b

def egcd(a, b):
    # Calculate the extended greatest common divisor of a and b
    if a == 0:
        return (b, 0, 1)
    g, y, x = egcd(b % a, a)
    return (g, x - (b // a) * y, y)

def mod_inverse(a, b):
    # Check if a and b are coprime
    if ext_euclid(a, b)[1] != 1:
        return None

    # Find the modular inverse
    x, y, g = ext_euclid(a, b)
    return x % b

def ext_euclid(a, b):
    if b == 0:
        return (1, 0, a)
    else:
        g, y, x = ext_euclid(b, a % b)
        return (x, y - a // b * x, g)

