def next_permutation(perm: list) -> bool:
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    else:
        # If no such number is found, the input is the last permutation in descending order
        return False

    # Find the smallest number that is larger and comes after it
    smallest = len(perm)
    for j in range(i + 1, len(perm)):
        if perm[j] > perm[i] and perm[j] < smallest:
            smallest = perm[j]

    # Swap the first smaller number with the smallest number that is larger and comes after it
    perm[i], perm[smallest] = perm[smallest], perm[i]

    # Reverse the order of numbers after the original first smaller number
    perm[i + 1:] = reversed(perm[i + 1:])

    return True

def next_permutation(perm: list) -> bool:
    if len(perm) <= 1:
        return False

    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i+1]:
        i -= 1

    if i == -1:
        return False

    j = len(perm) - 1
    while perm[j] <= perm[i]:
        j -= 1

    perm[i], perm[j] = perm[j], perm[i]

    perm[i+1:] = perm[len(perm)-1:i:-1]

    return True

