def next_permutation(perm):
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break

    # Swap it with the smallest number that is larger and comes after it
    for j in range(i + 1, len(perm)):
        if perm[i] < perm[j] and perm[j] < perm[i + 1]:
            break
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of numbers after the original first smaller number
    for k in range(i + 1, len(perm) // 2):
        perm[k], perm[len(perm) - k - 1] = perm[len(perm) - k - 1], perm[k]

    # If the input is the last permutation (in descending order), the function returns False, indicating no next permutation is possible
    if perm == list(reversed(perm)):
        return False
    return True

