def minimum_students_to_leave(heights):
    # Step 1: Initialize variables
    left, right = 0, len(heights) - 1
    peaks = []

    # Step 2: Find the peak indices
    while left < right:
        if heights[left] > heights[left + 1]:
            peaks.append(left)
            left += 1
        elif heights[right] > heights[right - 1]:
            peaks.append(right)
            right -= 1
        elif heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    # Step 3: Find the minimum number of students that need to leave
    min_leaves = 0
    for i in range(len(peaks) - 1):
        slope = (heights[peaks[i + 1]] - heights[peaks[i]]) / (peaks[i + 1] - peaks[i])
        if slope < 0:
            min_leaves += 1

    return min_leaves + 1

